        return
    if scope != ANCHOR_SCOPE:
        errors.append(f"{path_label}: unknown hashes.hash_scope {scope!r}; expected {ANCHOR_SCOPE} or none")
        return
    resolver = resolver or AnchorResolver()
    stale_out = errors if stale is None else stale
